script:
'use strict';
const BASE = String(triomi.baseUrl || 'https://www.wnacg.buzz').replace(/\/+$/, '');
if (!/^https:\/\/(?:www\.)?wn(?:acg|\d+)\.[a-z.]+$/.test(BASE)) throw new Error('WNACG 镜像地址无效');
function fail(message) { throw new Error('绅士漫画：' + message); }
function pageNumber(page) { if (!Number.isInteger(page) || page < 1) fail('页码无效'); return page; }
function image(value) {
  value = String(value || '').trim();
  if (/^\/{2,}/.test(value)) value = 'https://' + value.replace(/^\/+/, '');
  if (!/^https:\/\/[^\s"'<>\\]+$/.test(value)) fail('图片地址无效或不是 HTTPS');
  return value;
}
async function html(path) {
  const response = await triomi.fetch(BASE + path, {headers: {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:109.0) Gecko/20100101 Firefox/121.0',
    'Referer': BASE + '/'
  }});
  if (response.status !== 200) fail('HTTP ' + response.status + '，内容不存在、需要网站登录或站点验证');
  const title = await triomi.value(response.body, 'title', 'text');
  if (/Just a moment|Attention Required|验证|驗證/i.test(title || '') ||
      await triomi.value(response.body, '#challenge-form, #challenge-running', 'id')) fail('站点要求验证，请勿绕过');
  return response.body;
}
function albumId(url) {
  const match = /(?:^|\/)photos-(?:index|slide|list|gallery)(?:-page-\d+)?-aid-(\d+)(?:-sid-(\d+))?(?:-page-\d+)?\.html(?:$|[?#])/.exec(url);
  if (!match) fail('作品标识无效');
  return match[2] || match[1];
}
function albumUrl(id) { return BASE + '/photos-index-aid-' + id + '.html'; }
async function cards(path) {
  const doc = await html(path);
  const rows = await triomi.select(doc, '.gallary_item', {
    title: '.title > a', href: {selector: '.title > a', attr: 'href'},
    cover: {selector: 'img', attr: 'src'}
  });
  return rows.map(row => {
    if (!row.title) fail('作品标题缺失');
    const id = albumId(row.href);
    return {remoteId: id, title: row.title, type: 'manga', url: albumUrl(id), coverUrl: image(row.cover)};
  });
}
async function discover(url, page) {
  pageNumber(page);
  const match = /\/albums-favorite_ranking-page-\d+-type-(day|week|month|year)\.html$/.exec(url);
  return cards(match ? '/albums-favorite_ranking-page-' + page + '-type-' + match[1] + '.html'
    : '/albums-index-page-' + page + '.html');
}
async function search(keyword, page) {
  pageNumber(page);
  return cards('/search/index.php?s=create_time_DESC&q=' + encodeURIComponent(String(keyword || '')) + '&p=' + page);
}
async function searchTags() {
  const doc = await html('/albums-index-page-1.html');
  const rows = await triomi.select(doc, '#album_tabs a[href]', {title: '.', href: {selector: '.', attr: 'href'}});
  const seen = new Set();
  return rows.filter(row => {
    const match = /-cate-(\d+)\.html$/.exec(row.href);
    if (!row.title || !match || seen.has(match[1])) return false;
    seen.add(match[1]); row.id = 'category:' + match[1]; return true;
  }).map(row => ({id: row.id, label: row.title}));
}
async function searchTagged(keyword, page, tags) {
  if (!tags || !tags.length) return search(keyword, page);
  if (String(keyword || '').trim() || tags.length !== 1) fail('源站分类/标签不能与关键词或多个筛选组合');
  pageNumber(page);
  const category = /^category:(\d+)$/.exec(tags[0]);
  if (category) return cards('/albums-index-page-' + page + '-cate-' + category[1] + '.html');
  const tag = /^tag:(.+)$/.exec(tags[0]);
  if (tag) return cards('/albums-index-page-' + page + '-tag-' + encodeURIComponent(tag[1]) + '.html');
  fail('筛选项无效');
}
async function chapterRows(doc) {
  return triomi.select(doc, 'div.sr_compact a.tagshow[data-chid]', {
    id: {selector: '.', attr: 'data-chid'}, title: '.', date: {selector: '.', attr: 'title'}
  });
}
async function detail(url, snapshot) {
  const id = albumId(url || ''), path = '/photos-index-aid-' + id + '.html';
  const doc = await html(path), title = await triomi.value(doc, 'h2', 'text');
  if (!title) fail('内容不存在或需要网站登录；本适配暂不提供网站账号');
  const cover = await triomi.value(doc, 'div.uwthumb img', 'src');
  const info = await triomi.select(doc, 'div.uwconn label, div.uwconn p', {text: '.'});
  const tags = await triomi.values(doc, 'div.addtags a.tagshow', 'text');
  const item = {remoteId: id, title: title, type: 'manga', url: albumUrl(id),
    coverUrl: cover ? image(cover) : snapshot.coverUrl,
    author: await triomi.value(doc, 'div.uwuinfo p', 'text') || '', tags: tags,
    description: info.map(x => x.text).filter(x => /^(?:簡介|简介)[：:]/.test(x)).map(x => x.replace(/^[^：:]+[：:]\s*/, '')).join('\n'),
    status: info.some(x => /連載中|连载中/.test(x.text)) ? '连载中' : '已完结'};
  const links = await triomi.values(doc, 'div.f_left.paginator a[href]', 'href');
  let pages = 1;
  for (const link of links) {
    const match = /photos-index-aid-(\d+)-page-(\d+)\.html/.exec(link);
    if (match && match[1] === id) pages = Math.max(pages, Number(match[2]));
  }
  if (pages > 100) fail('合集分页超过安全限制');
  const all = await chapterRows(doc);
  if (!all.length && (pages > 1 || info.some(x => /^(?:章節|章节)[：:]/.test(x.text)))) fail('合集目录缺失，不能作为单章节读取');
  for (let page = 2; page <= pages; page++) {
    const rows = await chapterRows(await html('/photos-index-aid-' + id + '-page-' + page + '.html'));
    if (!rows.length) fail('合集分页目录为空，请重试');
    all.push(...rows);
  }
  const seen = new Set(), unique = all.filter(row => {
    if (!/^\d+$/.test(row.id) || !row.title) fail('合集章节数据无效');
    if (seen.has(row.id)) return false;
    seen.add(row.id); return true;
  }).reverse();
  const chapters = unique.length ? unique.map((row, index) => ({
    remoteId: row.id, title: row.title, url: albumUrl(row.id), sortIndex: index,
    releaseDate: (row.date.match(/\d{4}-\d{2}-\d{2}/) || [null])[0]
  })) : [{remoteId: id, title: '第 1 章', url: albumUrl(id), sortIndex: 0}];
  return {item: item, chapters: chapters};
}
async function content(url) {
  const id = albumId(url), doc = await html('/photos-gallery-aid-' + id + '.html');
  // Parse inert image literals, never eval downloaded scripts.
  const block = /\bimglist\s*=\s*(\[[\s\S]*?\])/.exec(doc);
  if (!block) fail('公开图片列表缺失，可能需要网站登录');
  const matches = block[1].match(/\/{2,}[^\s"'\\<>]+\.(?:jpeg|jpg|png|webp|gif)(?:\?[^\s"'\\<>]*)?/gi) || [];
  if (!matches.length || matches.length > 5000) fail('图片列表为空或超过安全限制');
  return {images: matches.map(image), imageHeaders: {'Referer': BASE + '/',
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:109.0) Gecko/20100101 Firefox/121.0'}};
}
